function mAdj(){modal('Stock Adjustment',`<div class="fr">${sel('Product','f1',popt(),'w')}${sel('Adjustment','f2','<option value="set">Set exact count</option><option value="add">Add units</option><option value="rem">Remove units</option>')}${fld('Quantity','f3','number','required min="0" value="0"')}${sel('Reason','f4','<option>Stock count correction</option><option>Damaged goods</option><option>Expired</option><option>Returned</option>','w')}</div><div class="info"><div><span>Current Stock</span><b id="cs"></b></div></div>`,'Save Adjustment',g=>{const p=byId(g('f1')),q=+g('f3'),m=g('f2'),pv=stat(p),o=p.stock;p.stock=m==='set'?q:m==='add'?o+q:Math.max(0,o-q);if(m==='add')S.mv.in+=q;if(m==='rem')S.mv.out+=Math.min(q,o);log('adjust',`${p.name}: ${o} → ${p.stock} (${g('f4')})`);changed(p,pv);renderAll();toast('Stock updated successfully')},()=>{const s=$('#f1');s.onchange=()=>$('#cs').textContent=byId(s.value).stock+' units';s.onchange()})}
