function mReorder(id){const p=byId(id);modal('Reorder Product',`<div class="info"><div><span>Product</span><b>${p.name}</b></div><div><span>Current Stock</span><b>${p.stock}</b></div><div><span>Reorder Level</span><b>${p.reorderLevel}</b></div><div><span>Average Daily Sales</span><b>${p.dailySales}/day</b></div><div><span>Supplier</span><b>${p.supplier}</b></div></div>${fld('Suggested Quantity (units)','f1','number','required min="1" value="'+suggest(p)+'"')}`,'Create Reorder',g=>{S.reorders.unshift({id:Date.now(),product:p.name,supplier:p.supplier,quantity:+g('f1'),status:'Pending',date:TODAY});log('reorder',`${p.name} × ${g('f1')}`);renderAll();toast('Reorder request created')})}
